import re
import pandas as pd

df = pd.read_csv('b3_supercon_data.csv')

def parse_comp(s):
    tokens = re.findall(r'([A-Z][a-z]?)(\d*\.?\d*)', s)
    d = {}
    for el, n in tokens:
        n = float(n) if n else 1.0
        d[el] = d.get(el, 0) + n
    total = sum(d.values())
    return {k: v/total for k,v in d.items()}

allowed = ['O','Cu','Ba','Sr','Y','Ca','La','Bi','Fe','Nb','C','Pr','As','B','Pb','Ce','Mo','V','Zn','Ni']
bounds = {
    'O': 0.697674, 'Cu': 0.454545, 'Ba': 0.333333, 'Sr': 0.285714, 'Y': 0.4,
    'Ca': 0.272727, 'La': 0.78, 'Bi': 0.521978, 'Fe': 0.502513, 'Nb': 0.98,
    'C': 0.972, 'Pr': 0.265043, 'As': 0.5, 'B': 1.0, 'Pb': 0.5, 'Ce': 0.28,
    'Mo': 1.0, 'V': 0.9918, 'Zn': 1.0, 'Ni': 0.6
}

# max fraction of each allowed element in THIS dataset
max_frac = {e: 0 for e in allowed}
max_comp = {e: None for e in allowed}
for i, row in df.iterrows():
    f = parse_comp(row['composition'])
    for e in allowed:
        if f.get(e,0) > max_frac[e]:
            max_frac[e] = f[e]
            max_comp[e] = (row['composition'], row['target'], f[e])

print(f'{"el":4s} {"data_max":10s} {"bound":10s} {"match":6s} formula')
for e in allowed:
    match = abs(max_frac[e] - bounds[e]) < 1e-5
    print(f'{e:4s} {max_frac[e]:10.6f} {bounds[e]:10.6f} {str(match):6s} {max_comp[e]}')
